/**
 * LINE Flex Message：日曆卡片風
 * 輸入：{ location, forecasts, count }
 * 輸出：{ location, message, cardCount }
 */

const data = $input.first().json;
// throw new Error("測試：模擬天氣資料驗證失敗");
const location = data.location || "未知地區";
const forecasts = (data.forecasts ?? []).slice(0, 5);



 // ===== 資料完整性驗證 =====

// 取得今天日期（台灣時間）
const today = $now
  .setZone("Asia/Taipei")
  .toFormat("yyyy-MM-dd");

// 用來檢查數值是否有效
function isValidNumber(value, min, max) {
  if (value === null || value === undefined || value === "") {
    return false;
  }

  const number = Number(value);

  return (
    Number.isFinite(number) &&
    number >= min &&
    number <= max
  );
}

// 儲存已檢查過的日期，避免重複
const checkedDates = new Set();

// 逐筆檢查天氣資料
for (const day of forecasts) {

  const date = String(day["日期"] ?? "").trim();

  // 1. 日期必須符合 yyyy-MM-dd
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new Error(`預報日期格式錯誤：${date}`);
  }

  // 2. 日期不能早於今天
  if (date < today) {
    throw new Error(`預報日期已過期：${date}`);
  }

  // 3. 不可以有重複日期
  if (checkedDates.has(date)) {
    throw new Error(`發現重複預報日期：${date}`);
  }

  checkedDates.add(date);

  // 4. 檢查最低、最高氣溫
  if (
    !isValidNumber(day["最低溫"], -50, 60) ||
    !isValidNumber(day["最高溫"], -50, 60)
  ) {
    throw new Error(`${date}：最低溫或最高溫無效`);
  }

  // 5. 最低溫不能大於最高溫
  if (Number(day["最低溫"]) > Number(day["最高溫"])) {
    throw new Error(`${date}：最低溫大於最高溫`);
  }

  // 6. 檢查三個時段的資料
  const periods = [
    ["早上氣溫", "早上降雨機率"],
    ["下午氣溫", "下午降雨機率"],
    ["晚上氣溫", "晚上降雨機率"]
  ];

  let availablePeriods = 0;

  for (const [tempKey, rainKey] of periods) {

    const temperature = day[tempKey];
    const rain = day[rainKey];

    // 該時段兩個欄位都沒有資料，允許略過
    if (
      (temperature === "" || temperature == null) &&
      (rain === "" || rain == null)
    ) {
      continue;
    }

    // 只要其中一欄有資料，兩欄都必須有效
    if (
      !isValidNumber(temperature, -50, 60) ||
      !isValidNumber(rain, 0, 100)
    ) {
      throw new Error(`${date}：${tempKey} 或 ${rainKey} 無效`);
    }

    availablePeriods++;
  }

  // 每天至少要有一個有效時段
  if (availablePeriods === 0) {
    throw new Error(`${date}：沒有可用的時段預報`);
  }
}




// ===== 地區主題配色 =====

const themes = {
  "彰化縣和美鎮": {
    locationBg: "#FFF3F6",
    locationText: "#884765",
    calendarBg: "#BB6589",
    weatherBg: "#F9E2EC",
    weatherText: "#91627A",
    temperatureText: "#713951",
    rainText: "#BB6589"
  },

  "臺中市大甲區": {
    locationBg: "#F4F7F9",
    locationText: "#2A4F5F",
    calendarBg: "#2A7086",
    weatherBg: "#DCEBE7",
    weatherText: "#5D6D79",
    temperatureText: "#2E4B5A",
    rainText: "#2C7FB8"
  }
};

// 根據地區選擇顏色
const theme = themes[location] ?? themes["臺中市大甲區"];


// ===== 1. 資料格式處理 =====

// null、undefined、空字串顯示為 —
// 數字 0 必須保留
function num(value) {
  if (value === null || value === undefined || value === "") {
    return "—";
  }

  const n = Number(value);
  return Number.isFinite(n) ? String(n) : "—";
}

function temp(value) {
  const n = num(value);
  return n === "—" ? "—" : `${n}°C`;
}

function rain(value) {
  const n = num(value);
  return n === "—" ? "—" : `${n}%`;
}

// 最低溫～最高溫
function tempRange(low, high) {
  const a = num(low);
  const b = num(high);

  if (a === "—" || b === "—") {
    return "—";
  }

  return `${a}°C ～ ${b}°C`;
}

// 將 2026-10-17 轉成 10/17、星期六
function formatDate(dateString) {
  const date = new Date(`${dateString}T00:00:00Z`);

  if (Number.isNaN(date.getTime())) {
    return { shortDate: "—", weekday: "—" };
  }

  const weekdays = [
    "星期日", "星期一", "星期二", "星期三",
    "星期四", "星期五", "星期六"
  ];

  return {
    shortDate: `${date.getUTCMonth() + 1}/${date.getUTCDate()}`,
    weekday: weekdays[date.getUTCDay()]
  };
}

// ===== 2. LINE Flex 共用文字元件 =====

function flexText(value, size, color, bold = false, extra = {}) {
  return {
    type: "text",
    text: String(value),
    size,
    color,
    ...(bold ? { weight: "bold" } : {}),
    ...extra
  };
}

// 表格標題列
function tableHeader() {
  return {
    type: "box",
    layout: "horizontal",
    contents: [
      {
        ...flexText("時段", "md", "#6D7D88", true),
        flex: 2
      },
      {
        ...flexText("平均氣溫", "md", "#6D7D88", true),
        align: "center",
        flex: 2
      },
      {
        ...flexText("降雨機率", "md", "#6D7D88", true),
        align: "end",
        flex: 2
      }
    ]
  };
}

// 表格資料列：早上、下午、晚上
function tableRow(period, temperature, probability) {
  return {
    type: "box",
    layout: "horizontal",
    margin: "md",
    contents: [
      {
        ...flexText(period, "lg", "#4F5F6B"),
        flex: 2
      },
      {
        ...flexText(temp(temperature), "lg", "#2C3E50", true),
        align: "center",
        flex: 2
      },
      {
        ...flexText(rain(probability), "lg", theme.rainText, true),
        align: "end",
        flex: 2
      }
    ]
  };
}

// ===== 3. 每一天建立一張日曆 Bubble =====

function createBubble(day) {
  const { shortDate, weekday } = formatDate(day["日期"]);

  const weather = String(day["主要天氣"] || "未知");

  const temperature = tempRange(
    day["最低溫"],
    day["最高溫"]
  );

  return {
    type: "bubble",
    size: "mega",
    body: {
      type: "box",
      layout: "vertical",
      paddingAll: "0px",
      contents: [

        // A. 最上方：地區名稱（淺灰白）
        {
          type: "box",
          layout: "vertical",
          backgroundColor: theme.locationBg,
          paddingTop: "14px",
          paddingBottom: "14px",
          paddingStart: "18px",
          paddingEnd: "18px",
          contents: [
            flexText(location, "xl", theme.locationText, true, {
              wrap: false
            })
          ]
        },

        // B. 日期與主要天氣（左右各 50%）
        {
          type: "box",
          layout: "horizontal",
          contents: [

            // 左側：日曆區
            {
              type: "box",
              layout: "vertical",
              width: "50%",
              backgroundColor: theme.calendarBg,
              paddingTop: "18px",
              paddingBottom: "18px",
              paddingStart: "16px",
              paddingEnd: "16px",
              justifyContent: "center",
              alignItems: "center",
              contents: [
                flexText(shortDate, "xxl", "#FFFFFF", true, {
                  align: "center"
                }),
                flexText(weekday, "xl", "#FFFFFF", false, {
                  margin: "md",
                  align: "center"
                })
              ]
            },

            // 右側：主要天氣及溫度
            {
              type: "box",
              layout: "vertical",
              width: "50%",
              backgroundColor: theme.weatherBg,
              paddingTop: "18px",
              paddingBottom: "18px",
              paddingStart: "16px",
              paddingEnd: "16px",
              justifyContent: "center",
              contents: [
                flexText(weather, "md", theme.weatherText, false, {
                  wrap: true
                }),
                flexText(temperature, "lg", theme.temperatureText, true, {
                  margin: "sm",
                  wrap: true
                })
              ]
            }
          ]
        },

        // C. 下半部：天氣統計表格
        {
          type: "box",
          layout: "vertical",
          paddingTop: "18px",
          paddingBottom: "18px",
          paddingStart: "18px",
          paddingEnd: "18px",
          contents: [

            tableHeader(),

            // 標題與第一筆資料之間
            {
              type: "separator",
              margin: "md"
            },

            // 早上
            tableRow(
              "早上",
              day["早上氣溫"],
              day["早上降雨機率"]
            ),

            {
              type: "separator",
              margin: "md"
            },

            // 下午
            tableRow(
              "下午",
              day["下午氣溫"],
              day["下午降雨機率"]
            ),

            {
              type: "separator",
              margin: "md"
            },

            // 晚上：下方不加分隔線
            tableRow(
              "晚上",
              day["晚上氣溫"],
              day["晚上降雨機率"]
            ),

            // E. 資料來源
            flexText(
              "資料來源：OpenWeatherMap",
              "xs",
              "#94A3AF",
              false,
              {
                margin: "lg"
              }
            )
          ]
        }
      ]
    }
  };
}

// ===== 4. 產生 Carousel =====

// 找不到預報時，回覆一般文字
if (forecasts.length === 0) {
  return [{
    json: {
      location,
      message: {
        type: "text",
        text: `${location}目前沒有可用的天氣預報，請稍後再試。`
      },
      cardCount: 0
    }
  }];
}

// 將每日資料轉成 Bubble
const bubbles = forecasts.map(createBubble);

// 包裝成 LINE Flex Message
const message = {
  type: "flex",
  altText: `${location}未來五天天氣預報`,
  contents: {
    type: "carousel",
    contents: bubbles
  }
};

// ===== 5. 回傳給 LINE Messaging 節點 =====

return [{
  json: {
    location,
    message,
    cardCount: bubbles.length
  }
}];

 // 1. 從原始 Webhook 取得已解析的 JSON Body
const body = $("Webhook").first().json.body;

// 2. 確認 Body 是合法的物件
if (
  !body ||
  typeof body !== "object" ||
  Array.isArray(body)
) {
  throw new Error("LINE Webhook Body 格式錯誤");
}

// 3. 確認 events 是陣列
if (!Array.isArray(body.events)) {
  throw new Error("LINE Webhook 缺少 events 陣列");
}

// 4. 取得 LINE 事件
const events = body.events;

// 5. 輸出給下一個節點
return [{
  json: {
    body,
    events
  }
}];

/*
 * 根據 LINE 使用者輸入的指令，
 * 從 Google Sheets 資料中取得指定地區的未來預報。
 */

// 1. 取得使用者原本的 LINE 訊息
const message = $("Edit Fields").first().json.message;

// 2. 設定指令與地區的對應關係
const locationMap = {
  "查詢天氣_和美": "彰化縣和美鎮",
  "查詢天氣_大甲": "臺中市大甲區"
};

// 3. 根據 LINE 指令取得地區
const location = locationMap[message];

// 如果找不到地區，停止執行
if (!location) {
  throw new Error(`無法辨識的天氣查詢指令`);
}

// 4. 取得台灣今天的日期
const today = $now
  .setZone("Asia/Taipei")
  .toFormat("yyyy-MM-dd");

// 5. 取得 Google Sheets 回傳的所有資料
const rows = $input.all()
  .map(item => item.json)
  .filter(row => {

    const id = String(row["唯一識別碼"] ?? "");
    const date = String(row["日期"] ?? "");

    // 只保留符合地區，而且日期不早於今天的預報
    return (
      id.endsWith(`_${location}`) &&
      date >= today
    );
  })

  // 按照預報日期由近到遠排序
  .sort((a, b) =>
    String(a["日期"]).localeCompare(String(b["日期"]))
  )

  // 最多顯示五天
  .slice(0, 5);

// 6. 將結果交給 LINE Flex 圖卡節點
return [{
  json: {
    location,
    forecasts: rows,
    count: rows.length
  }
}];
